    public void show_automation_editor_in_lane(Control o,Control editor)
    {
        if(editor.Get("session").AsGodotObject()!=Session(o)){notice(o,"Return to the original document before creating a lane.");return;}var target=new Settings{["owner_kind"]=editor.Get("owner_kind"),["owner_id"]=editor.Get("owner_id"),["effect_id"]=editor.Get("effect_id"),["parameter"]=editor.Get("parameter")};foreach(var raw in Items(Document(o),"tracks")){var track=raw.AsGodotDictionary();if(_frameLanes.is_lane(track)&&_frameLanes.key(Get(track,"automation_target",new Settings()).AsGodotDictionary())==_frameLanes.key(target)){Items(Session(o),"selected_ids").Clear();Session(o).Set("selected_track",track["id"].AsString());Session(o).EmitSignal("selection_changed");automation_lane_editor(o,track["id"].AsString());return;}}var info=_frameLanes.resolve(Document(o),target);if(info.Count==0){notice(o,"The automation target no longer exists.");return;}string selected="";SessionAction(o,"Show automation in timeline",()=>{using var documents=new AudioDocumentOperations();var lane=documents.add_track(Document(o),info["label"].AsString(),"automation");lane["automation_target"]=target.Duplicate(true);selected=lane["id"].AsString();Items(Session(o),"selected_ids").Clear();Session(o).Set("selected_track",selected);});Session(o).EmitSignal("selection_changed");automation_lane_editor(o,selected);
    }
    public void automation_lane_editor(Control o,string laneId)
