n(o,modulation,"Shape",new GArray{"sine","triangle","saw","square","random step","envelope"},"sine",value=>settings["shape"]=value);CheckAction(modulation,"Beat sync",true,value=>settings["sync"]=value);NumberAction(o,modulation,"Beats/cycle",1,.0625,32,.0625,value=>settings["beats"]=value);NumberAction(o,modulation,"Rate Hz",1,.01,20,.01,value=>settings["rate"]=value);NumberAction(o,modulation,"Center",settings["center"].AsDouble(),low,high,.01,value=>settings["center"]=value);NumberAction(o,modulation,"Depth",settings["depth"].AsDouble(),0,high-low,.01,value=>settings["depth"]=value);NumberAction(o,modulation,"Seed",1,0,2147483647,1,value=>settings["seed"]=(long)value);var actions=new HFlowContainer();host.AddChild(actions);ActionButton(actions,"Generate / replace curve",()=>editor.Call("modulate",settings));ActionButton(actions,"Clear linked curve",()=>editor.Call("clear_points"));ActionButton(actions,"Retarget lane...",()=>{windowNode.QueueFree();automation_lane_target_dialog(o,laneId,new Settings());});label(host,"Clip times are relative to the clip; track/master times are absolute. Gain/pan share the existing playback and export curves. Pitch and effect automation retain their existing offline backend requirements and approximation limits.");
    }
